//! Reviewed item identity projection for `item_ledger`.
//!
//! The asset is generated by the extraction pipeline from the reviewed
//! item-ledger contract and re-derived from MAIN.EXE.  It binds every one of the
//! 179 used source item identities to the existing runtime item controller
//! (`items.zig` / `items.json`) and states, per identity, whether the runtime
//! can represent it.  No address, LBA or record offset appears here; that
//! provenance lives in the extraction report.
//!
//! This module validates the packet independently: it recomputes the semantic
//! identity digest, re-checks every controller binding against the live
//! `field.items.Id` enum (name, use count, appraisal state) and refuses a stale
//! or hand-edited packet.
const std = @import("std");
const field = @import("field");

pub const schema = "suikoden-item-shared-ledger/1";
pub const item_count = 179;
pub const shared_capacity = 7;

/// Packet pins are regenerated by kit/tools/generate_item_ledger.py; reviewed inputs remain fixed.
pub const expected_asset_sha256 = "8275f8f82b8c8d05a56c2db44d3544c991ddbfab9d8367d6f0d7c44c96f7a5e5";
pub const expected_identity_digest = "0f64dc33cf92cf76";
pub const expected_item_contracts_sha256 = "ca19a0f12154b99a6c1275cafe2b420e0f14502885548830a40f551920521fa9";
pub const expected_reviewed_packet_schema = "suikoden-full-item-contracts/1";
pub const expected_reviewed_items_digest = "b23023b00e0e1aef";
pub const expected_main_file_sha256 = "439a166609dab8cde26249bd7661a835e4d55e79bb37a964761c981524e89d95";
pub const expected_main_image_sha256 = "e123263c3046a7283d8ca26598185672ed3f8de72d97f5efb0ee8e88ccaa55fa";

pub const Category = enum {
    equipment_head,
    equipment_body,
    equipment_shield,
    equipment_feet_or_accessory,
    consumable,
    stat_rune_piece,
    key_tool,
    weapon_fragment,
    appraised_decoration,
    key_item,
};
pub const Ownership = enum {
    personal_equipment,
    usable_bundle,
    usable_tool,
    weapon_attachment,
    appraisal,
    shared_key,
};
pub const EquipmentSlot = enum { head, body, shield, feet_or_accessory };
pub const Fragment = enum { fire, water, wind, thunder, earth };
pub const Operation = enum {
    shared_acquire,
    shared_remove,
    shared_query,
    transfer_check,
    consume_preview,
};
pub const ControllerKind = enum { unbound, items_enum };
pub const UnboundReason = enum {
    unsupported,
    no_items_enum_member,
    appraisal_state_unsupported,
    use_count_mismatch,
    ambiguous_name,
};
pub const Effect = enum { shared_acquire, shared_remove, deposit_identified };
pub const OperationStatus = enum { bound, bound_to_storage_owner, blocked };

pub const Controller = struct {
    kind: ControllerKind,
    tag: ?[]const u8 = null,
    reason: ?UnboundReason = null,
};
pub const Item = struct {
    id: []const u8,
    source_item_id: u16,
    label: []const u8,
    category: Category,
    ownership: Ownership,
    price: u32,
    max_uses: u8,
    usable: bool,
    requires_target: bool,
    battle_usable: bool,
    appraisal_tier: u8,
    equipment_slot: ?EquipmentSlot,
    equipment_type_mask: u8,
    weapon_fragment: ?Fragment,
    duplicate_label: bool,
    supported_operations: []const Operation,
    controller: Controller,
};
pub const CategorySummary = struct { id: Category, ownership: Ownership, count: u16 };
pub const SourceOperation = struct { id: []const u8, effect: Effect, status: OperationStatus };
pub const Engine = struct {
    shared_capacity: u8,
    duplicate_acquisition: []const u8,
    append: []const u8,
    remove: []const u8,
    query: []const u8,
    uses: []const u8,
    transfer: []const u8,
    equipment_eligibility: []const u8,
    source_operations: []const SourceOperation,
};
pub const Bindings = struct {
    items_enum_bound: u16,
    unbound: u16,
    runtime_tags: u16,
    degraded_runtime_tags: []const []const u8,
    unbound_treatment: []const u8,
};
pub const Blocker = struct { code: []const u8, detail: []const u8 };
pub const DuplicateGroup = struct { label: []const u8, source_item_ids: []const u16 };
pub const FragmentBinding = struct { element: Fragment, id: []const u8, source_item_id: u16 };
pub const Identities = struct {
    stable_id_policy: []const u8,
    duplicate_label_groups: []const DuplicateGroup,
    trailing_space_labels: []const []const u8,
    weapon_fragments: []const FragmentBinding,
};
pub const Source = struct {
    reviewed_packet_commit: []const u8,
    reviewed_packet_schema: []const u8,
    item_contracts_sha256: []const u8,
    reviewed_items_digest: []const u8,
    main_file_sha256: []const u8,
    main_image_sha256: []const u8,
    identity_digest: []const u8,
};
pub const Packet = struct {
    schema: []const u8,
    source: Source,
    items: []const Item,
    categories: []const CategorySummary,
    engine: Engine,
    bindings: Bindings,
    blockers: []const Blocker,
    identities: Identities,
};

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    if (bytes.len > 4 * 1024 * 1024) return error.AssetTooLarge;
    var hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
    if (!std.mem.eql(u8, &std.fmt.bytesToHex(hash, .lower), expected_asset_sha256))
        return error.InvalidAssetHash;
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{ .allocate = .alloc_always });
    errdefer parsed.deinit();
    try validatePacket(parsed.value);
    return parsed;
}

// --------------------------------------------------------------------------- //
// validation
// --------------------------------------------------------------------------- //
pub fn validatePacket(packet: Packet) !void {
    if (!std.mem.eql(u8, packet.schema, schema)) return error.InvalidSchema;
    if (packet.source.reviewed_packet_commit.len != 40) return error.InvalidSourcePin;
    if (!std.mem.eql(u8, packet.source.reviewed_packet_schema, expected_reviewed_packet_schema) or
        !std.mem.eql(u8, packet.source.item_contracts_sha256, expected_item_contracts_sha256) or
        !std.mem.eql(u8, packet.source.reviewed_items_digest, expected_reviewed_items_digest) or
        !std.mem.eql(u8, packet.source.main_file_sha256, expected_main_file_sha256) or
        !std.mem.eql(u8, packet.source.main_image_sha256, expected_main_image_sha256))
        return error.InvalidSourcePin;
    if (packet.items.len != item_count) return error.InvalidItemCount;
    if (packet.engine.shared_capacity != shared_capacity) return error.InvalidEngine;
    if (!std.mem.eql(u8, packet.engine.duplicate_acquisition, "permitted_by_source_append"))
        return error.InvalidEngine;
    for ([_][]const u8{ packet.engine.append, packet.engine.remove, packet.engine.query, packet.engine.uses, packet.engine.transfer, packet.engine.equipment_eligibility }) |field_text|
        if (field_text.len == 0) return error.InvalidEngine;
    const operations = packet.engine.source_operations;
    if (operations.len != 3) return error.InvalidEngine;
    if (operations[0].effect != .shared_acquire or operations[0].status != .bound) return error.InvalidEngine;
    if (operations[1].effect != .shared_remove or operations[1].status != .bound) return error.InvalidEngine;
    if (operations[2].effect != .deposit_identified or
        operations[2].status != .bound_to_storage_owner) return error.InvalidEngine;
    if (packet.blockers.len < 3) return error.InvalidBlockers;

    var counts: [10]u16 = @splat(0);
    var bound: u16 = 0;
    var unbound: u16 = 0;
    var labels_trailing: usize = 0;
    for (packet.items, 0..) |item, index| {
        if (item.source_item_id != index + 1) return error.InvalidItem;
        if (item.id.len == 0 or item.label.len == 0) return error.InvalidItem;
        for (packet.items[0..index]) |previous| {
            if (std.mem.eql(u8, item.id, previous.id)) return error.InvalidItem;
        }
        try validateItem(item);
        counts[@backingInt(item.category)] += 1;
        switch (item.controller.kind) {
            .items_enum => bound += 1,
            .unbound => unbound += 1,
        }
        if (item.label[item.label.len - 1] == ' ') labels_trailing += 1;
    }
    if (bound != packet.bindings.items_enum_bound or unbound != packet.bindings.unbound)
        return error.InvalidBindingCount;
    if (bound + unbound != item_count) return error.InvalidBindingCount;
    if (packet.bindings.runtime_tags != std.enums.values(field.items.Id).len or packet.bindings.runtime_tags != bound + packet.bindings.degraded_runtime_tags.len) return error.InvalidBindingCount;
    if (!std.mem.eql(u8, packet.bindings.unbound_treatment, "typed_failure_without_runtime_identity"))
        return error.InvalidBindingCount;

    var declared_total: u16 = 0;
    for (packet.categories) |summary| {
        if (summary.count != counts[@backingInt(summary.id)]) return error.InvalidCategory;
        declared_total += summary.count;
    }
    for (packet.categories, 0..) |summary, index| {
        for (packet.categories[0..index]) |previous| {
            if (previous.id == summary.id) return error.InvalidCategory;
        }
        if (summary.ownership != ownershipFor(summary.id)) return error.InvalidCategory;
    }
    if (packet.categories.len != 10 or declared_total != item_count) return error.InvalidCategory;

    // Detail: the identity table itself.
    if (packet.identities.duplicate_label_groups.len != 1) return error.InvalidIdentity;
    const group = packet.identities.duplicate_label_groups[0];
    if (!std.mem.eql(u8, group.label, "Mathiu's letter") or group.source_item_ids.len != 2 or
        group.source_item_ids[0] != 90 or group.source_item_ids[1] != 179) return error.InvalidIdentity;
    if (packet.identities.trailing_space_labels.len != 2 or labels_trailing != 2) return error.InvalidIdentity;
    if (!std.mem.eql(u8, packet.identities.trailing_space_labels[0], "lover_s_garden") or
        !std.mem.eql(u8, packet.identities.trailing_space_labels[1], "prodigy")) return error.InvalidIdentity;
    if (packet.identities.weapon_fragments.len != 5) return error.InvalidIdentity;
    var fragment_mask: u5 = 0;
    for (packet.identities.weapon_fragments, 0..) |binding, index| {
        if (binding.source_item_id != 57 + index) return error.InvalidIdentity;
        if (@backingInt(binding.element) != index) return error.InvalidIdentity;
        const item = packet.items[binding.source_item_id - 1];
        if (item.weapon_fragment != binding.element or !std.mem.eql(u8, item.id, binding.id))
            return error.InvalidIdentity;
        fragment_mask |= @as(u5, 1) << @intCast(index);
    }
    if (fragment_mask != 0x1f) return error.InvalidIdentity;

    // The runtime-only identities are named, not hidden, and they must still be
    // real `items.Id` members.
    for (packet.bindings.degraded_runtime_tags) |tag| {
        const runtime = std.meta.stringToEnum(field.items.Id, tag) orelse return error.InvalidControllerBinding;
        for (packet.items) |item| {
            if (item.controller.kind != .items_enum) continue;
            if (std.mem.eql(u8, item.controller.tag.?, tag)) return error.InvalidControllerBinding;
        }
        if (runtime.decoration()) return error.InvalidControllerBinding;
    }

    const digest = identityDigest(packet);
    if (digest != std.fmt.parseInt(u64, expected_identity_digest, 16) catch return error.InvalidDigest)
        return error.InvalidDigest;
    if (!std.mem.eql(u8, packet.source.identity_digest, expected_identity_digest))
        return error.InvalidDigest;
}

fn validateItem(item: Item) !void {
    if (item.ownership != ownershipFor(item.category)) return error.InvalidItem;
    const equipment = switch (item.category) {
        .equipment_head, .equipment_body, .equipment_shield, .equipment_feet_or_accessory => true,
        else => false,
    };
    const expected_slot: ?EquipmentSlot = switch (item.category) {
        .equipment_head => .head,
        .equipment_body => .body,
        .equipment_shield => .shield,
        .equipment_feet_or_accessory => .feet_or_accessory,
        else => null,
    };
    if (equipment) {
        if (item.equipment_slot == null or item.equipment_slot.? != expected_slot.? or item.equipment_type_mask == 0 or item.max_uses != 0 or item.usable or item.appraisal_tier != 0 or item.weapon_fragment != null) return error.InvalidItem;
    } else if (item.equipment_slot != null or item.equipment_type_mask != 0) return error.InvalidItem;

    if (item.category == .appraised_decoration) {
        if (item.appraisal_tier < 1 or item.appraisal_tier > 3 or item.usable) return error.InvalidItem;
    } else if (item.appraisal_tier != 0) return error.InvalidItem;
    if (item.category == .weapon_fragment) {
        if (item.weapon_fragment == null or item.usable or item.max_uses != 0) return error.InvalidItem;
    } else if (item.weapon_fragment != null) return error.InvalidItem;
    if (!item.usable and item.max_uses != 0) return error.InvalidItem;
    if (item.usable and item.max_uses == 0 and item.category != .key_tool) return error.InvalidItem;

    var has_consume = false;
    var seen: [5]bool = @splat(false);
    for (item.supported_operations) |operation| {
        if (seen[@backingInt(operation)]) return error.InvalidItem;
        seen[@backingInt(operation)] = true;
        if (operation == .consume_preview) has_consume = true;
    }
    for ([_]Operation{ .shared_acquire, .shared_remove, .shared_query, .transfer_check }) |required| {
        if (!seen[@backingInt(required)]) return error.InvalidItem;
    }
    if (has_consume != item.usable) return error.InvalidItem;
    if (item.duplicate_label != std.mem.eql(u8, item.label, "Mathiu's letter")) return error.InvalidItem;

    switch (item.controller.kind) {
        .items_enum => {
            const tag = item.controller.tag orelse return error.InvalidControllerBinding;
            if (item.controller.reason != null or !std.mem.eql(u8, tag, item.id)) return error.InvalidControllerBinding;
            const runtime = std.meta.stringToEnum(field.items.Id, tag) orelse
                return error.InvalidControllerBinding;
            if (!std.mem.eql(u8, runtime.name(), item.label)) return error.InvalidControllerBinding;
            if (runtime.maxUses() != @as(u16, item.max_uses)) return error.InvalidControllerBinding;
            if (runtime.sourceId() != item.source_item_id or runtime.equipment() != (item.equipment_slot != null)) return error.InvalidControllerBinding;
            if (runtime.decoration() != (item.appraisal_tier > 0)) return error.InvalidControllerBinding;
        },
        .unbound => {
            const reason = item.controller.reason orelse return error.InvalidControllerBinding;
            if (item.controller.tag != null) return error.InvalidControllerBinding;
            if (reason == .unsupported) return error.InvalidControllerBinding;
            // Labels can repeat; only the source-stable identity can shadow an enum member.
            if (std.meta.stringToEnum(field.items.Id, item.id)) |runtime| {
                if (reason != .appraisal_state_unsupported or runtime.decoration() or
                    runtime.maxUses() != @as(u16, item.max_uses)) return error.InvalidControllerBinding;
            }
        },
    }
}

pub fn ownershipFor(category: Category) Ownership {
    return switch (category) {
        .equipment_head, .equipment_body, .equipment_shield, .equipment_feet_or_accessory => .personal_equipment,
        .consumable, .stat_rune_piece => .usable_bundle,
        .key_tool => .usable_tool,
        .weapon_fragment => .weapon_attachment,
        .appraised_decoration => .appraisal,
        .key_item => .shared_key,
    };
}

// --------------------------------------------------------------------------- //
// semantic digest
// --------------------------------------------------------------------------- //
fn categoryCode(category: Category) u8 {
    return @backingInt(category) + 1;
}
fn ownershipCode(ownership: Ownership) u8 {
    return @backingInt(ownership) + 1;
}
fn fragmentCode(fragment: ?Fragment) u8 {
    return if (fragment) |value| @backingInt(value) + 1 else 0;
}
fn reasonCode(reason: ?UnboundReason) u8 {
    const value = reason orelse return 0;
    return switch (value) {
        .unsupported => 0,
        .no_items_enum_member => 1,
        .appraisal_state_unsupported => 2,
        .use_count_mismatch => 3,
        .ambiguous_name => 4,
    };
}
fn statusCode(status: OperationStatus) u8 {
    return @backingInt(status) + 1;
}
fn effectCode(effect: Effect) u8 {
    return @backingInt(effect) + 1;
}

fn writeU16(hasher: *std.hash.Fnv1a_64, value: u16) void {
    var buffer: [2]u8 = undefined;
    std.mem.writeInt(u16, &buffer, value, .little);
    hasher.update(&buffer);
}
fn writeU32(hasher: *std.hash.Fnv1a_64, value: u32) void {
    var buffer: [4]u8 = undefined;
    std.mem.writeInt(u32, &buffer, value, .little);
    hasher.update(&buffer);
}
fn writeText(hasher: *std.hash.Fnv1a_64, value: []const u8, length_width: u8) void {
    switch (length_width) {
        1 => hasher.update(&.{@intCast(value.len)}),
        else => writeU16(hasher, @intCast(value.len)),
    }
    hasher.update(value);
}

pub fn identityDigest(packet: Packet) u64 {
    var hasher = std.hash.Fnv1a_64.init();
    writeU16(&hasher, @intCast(packet.items.len));
    for (packet.items) |item| {
        writeU16(&hasher, item.source_item_id);
        hasher.update(&.{categoryCode(item.category)});
        hasher.update(&.{ownershipCode(item.ownership)});
        writeU32(&hasher, item.price);
        hasher.update(&.{item.max_uses});
        const flags: u8 = @as(u8, @intFromBool(item.usable)) |
            (@as(u8, @intFromBool(item.requires_target)) << 1) |
            (@as(u8, @intFromBool(item.battle_usable)) << 2) |
            (@as(u8, @intFromBool(item.duplicate_label)) << 3);
        hasher.update(&.{flags});
        hasher.update(&.{item.equipment_type_mask});
        hasher.update(&.{item.appraisal_tier});
        hasher.update(&.{fragmentCode(item.weapon_fragment)});
        hasher.update(&.{@backingInt(item.controller.kind)});
        hasher.update(&.{reasonCode(item.controller.reason)});
        if (item.controller.kind == .items_enum) {
            writeText(&hasher, item.controller.tag.?, 1);
        } else {
            hasher.update(&.{0});
        }
        writeText(&hasher, item.id, 1);
        writeText(&hasher, item.label, 2);
        hasher.update(&.{@intCast(item.supported_operations.len)});
        for (item.supported_operations) |operation| hasher.update(&.{@backingInt(operation) + 1});
    }
    hasher.update(&.{packet.engine.shared_capacity});
    hasher.update(&.{@intCast(packet.engine.source_operations.len)});
    for (packet.engine.source_operations) |operation| {
        hasher.update(&.{effectCode(operation.effect)});
        hasher.update(&.{statusCode(operation.status)});
    }
    hasher.update(&.{@intCast(packet.categories.len)});
    for (packet.categories) |summary| {
        hasher.update(&.{categoryCode(summary.id)});
        writeU16(&hasher, summary.count);
    }
    hasher.update(&.{@intCast(packet.bindings.degraded_runtime_tags.len)});
    for (packet.bindings.degraded_runtime_tags) |tag| writeText(&hasher, tag, 1);
    return hasher.final();
}

// --------------------------------------------------------------------------- //
// lookups
// --------------------------------------------------------------------------- //
pub fn findBySourceId(packet: Packet, source_item_id: u16) ?*const Item {
    if (source_item_id == 0 or source_item_id > packet.items.len) return null;
    return &packet.items[source_item_id - 1];
}
pub fn findById(packet: Packet, id: []const u8) ?*const Item {
    if (id.len == 0) return null;
    for (packet.items) |*item| {
        if (std.mem.eql(u8, item.id, id)) return item;
    }
    return null;
}

pub fn sharedKey(packet: Packet, id: []const u8) !*const Item {
    const item = findById(packet, id) orelse return error.UnknownIdentity;
    if (item.ownership != .shared_key) return error.InvalidSharedItem;
    return item;
}
/// Resolve a display label.  The two Mathiu's letter ids share a label, so a
/// label lookup must refuse the ambiguity instead of picking one.
pub fn findByLabel(packet: Packet, label: []const u8) !*const Item {
    var found: ?*const Item = null;
    for (packet.items) |*item| {
        if (!std.mem.eql(u8, item.label, label)) continue;
        if (found != null) return error.AmbiguousLabel;
        found = item;
    }
    return found orelse error.UnknownIdentity;
}
pub fn sourceOperation(packet: Packet, id: []const u8) ?*const SourceOperation {
    for (packet.engine.source_operations) |*operation| {
        if (std.mem.eql(u8, operation.id, id)) return operation;
    }
    return null;
}
